def replace_words(words_to_replace, replacement_words, text):
    if len(words_to_replace) != len(replacement_words):
        return 'Error: Both the arrays should have equal length'
    replacement_dict = dict(zip(words_to_replace, replacement_words))
    words = text.split()
    modified_words = [replacement_dict.get(word, word) for word in words]
    return ' '.join(modified_words)

