def factorial(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def findUnsortedSubarray(nums):
    start = -1
    end = -1
    n = len(nums)
    for i in range(n-1):
        if nums[i] > nums[i+1]:
            start = i
            break
    for i in range(n-1, 0, -1):
        if nums[i] < nums[i-1]:
            end = i
            break
    return end - start + 1 if start != -1 else 0

